//! 🧬️ SemioGraphMutation — document mutation dispatch. Semantic vocabulary derived from
//! `📸️snapshot/🦀️component.rs`'s `SemioGraphSnapshot` shape (two id-keyed sets with no
//! user-meaningful display order — `nodes`/`edges`, each node carrying its own nested `ports`/
//! `properties` collections) per `../SEMANTIC-MUTATIONS-OVERHAUL/📓️taxonomy.md`/
//! `📓️derivation-rules.md`. `impl protocol::Mutation`/`SemanticMutation` below are generated by
//! `#[derive(dsl::Mutations)]` — never hand-written.
//!
//! Edges are ID-KEYED ENTITIES, not relationships — `create-edge`/`delete-edge` (entity lifecycle),
//! never `connect`/`disconnect`, since `source`/`target` are ordinary data fields on the edge
//! entity, and the edge needs its own referenceable id for future property/port extension. Both
//! `nodes` and `edges` are id-keyed sets with no display order, so there is no `reorder-nodes`/
//! `reorder-edges` mutation (`📓️derivation-rules.md` rule 2). `ports: Vec<SemioGraphPort>`/
//! `properties: Vec<SemioValueEntry>` (nested inside each node) are intrinsically ordered,
//! anonymous collections, addressed the same way `✳️text`'s `marks: Vec<SemioTextMark>` is:
//! `add-node-port`/`remove-node-port` and `add-node-property`/`remove-node-property` take
//! `{node_id, index}`, `add`/`remove` per the core verb table's "attach/detach a set-like member"
//! entry.
//!
//! Every triad leaf is mounted directly as a `mutations`-sibling module in `📦️glue.rs` (owned by
//! the stdio W2/table-graph orchestrator, so no self-wiring `#[path = "."]` blocks are needed here).

use crate::artifacts::semio::standards::v1::subsets::graph::schema::diff::SemioGraphDiff;
use crate::artifacts::semio::standards::v1::subsets::graph::schema::snapshot::SemioGraphSnapshot;
use serde::{Deserialize, Serialize};

//#region 🔖️Leaves
use super::add_node_port;
use super::add_node_property;
use super::change_node_kind;
use super::change_node_label;
use super::create_edge;
use super::create_node;
use super::delete_edge;
use super::delete_node;
use super::move_node;
use super::remove_node_port;
use super::remove_node_property;
//#endregion 🔖️Leaves

//#region 🔖️Mutations
/// 🧬️ Every variant wraps exactly one `protocol::MutationKind<SemioGraphSnapshot, SemioGraphMutation>`
/// payload struct declared in the corresponding triad leaf's `🦠️mutation/🦀️component.rs`. Eleven
/// triads, in dispatch order: node lifecycle (`create-node`/`delete-node`), node scalar fields
/// (`change-node-kind`/`change-node-label`/`move-node`), node nested collections
/// (`add-node-port`/`remove-node-port`/`add-node-property`/`remove-node-property`), then edge
/// lifecycle (`create-edge`/`delete-edge`).
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, dsl::Mutations)]
#[mutations(snapshot = SemioGraphSnapshot, diff = SemioGraphDiff, schema = "s.stdio.semio.graph")]
pub enum SemioGraphMutation {
    CreateNode(create_node::mutation::CreateNode),
    DeleteNode(delete_node::mutation::DeleteNode),
    ChangeNodeKind(change_node_kind::mutation::ChangeNodeKind),
    ChangeNodeLabel(change_node_label::mutation::ChangeNodeLabel),
    MoveNode(move_node::mutation::MoveNode),
    AddNodePort(add_node_port::mutation::AddNodePort),
    RemoveNodePort(remove_node_port::mutation::RemoveNodePort),
    AddNodeProperty(add_node_property::mutation::AddNodeProperty),
    RemoveNodeProperty(remove_node_property::mutation::RemoveNodeProperty),
    CreateEdge(create_edge::mutation::CreateEdge),
    DeleteEdge(delete_edge::mutation::DeleteEdge),
}
//#endregion 🔖️Mutations

//#region 🧪️Tests
#[cfg(test)]
mod tests {
    use super::*;
    use crate::artifacts::semio::standards::v1::subsets::any::schema::geometry::SemioPoint2;
    use crate::artifacts::semio::standards::v1::subsets::graph::schema::snapshot::{GraphEdgeId, GraphNodeId, SemioGraphEdge, SemioGraphNode, SemioGraphPort, SemioGraphPortKind};
    use crate::artifacts::semio::standards::v1::subsets::value::schema::snapshot::{SemioValue, SemioValueEntry};
    use protocol::{Mutation, MutationDiff, SemanticMutation};

    async fn fixture() -> SemioGraphSnapshot {
        SemioGraphSnapshot {
            nodes: vec![
                SemioGraphNode {
                    id: GraphNodeId::new("n1"),
                    kind: "source".into(),
                    label: "Source".into(),
                    position: SemioPoint2 { x: 0.0, y: 0.0 },
                    ports: vec![SemioGraphPort { name: "out".into(), kind: SemioGraphPortKind::Out }],
                    properties: vec![],
                },
                SemioGraphNode { id: GraphNodeId::new("n2"), kind: "sink".into(), label: "Sink".into(), position: SemioPoint2 { x: 10.0, y: 10.0 }, ports: vec![], properties: vec![] },
            ],
            edges: vec![SemioGraphEdge { id: GraphEdgeId::new("e1"), source: GraphNodeId::new("n1"), target: GraphNodeId::new("n2"), kind: "flow".into(), label: "Main".into() }],
            ..Default::default()
        }
    }

    /// 🔧️ `nodes`/`edges` are id-keyed SETS with no user-meaningful display order (this facet's
    /// own dispatch doc comment) — `create-node`'s diff always APPENDS, so a cascading
    /// `delete-node` inverse that recreates a node deleted from the middle of `base.nodes`
    /// legitimately lands it at the end. Comparing snapshots for round-trip fidelity must therefore
    /// be order-INSENSITIVE over `nodes`/`edges` (same SET, not same SEQUENCE) — a physical `Vec`
    /// is the storage representation, not the domain's equality contract.
    async fn sorted_by_id(mut s: SemioGraphSnapshot) -> SemioGraphSnapshot {
        s.nodes.sort_by(|a, b| a.id.value.cmp(&b.id.value));
        s.edges.sort_by(|a, b| a.id.value.cmp(&b.id.value));
        s
    }

    async fn round_trip(base: &SemioGraphSnapshot, operation: &SemioGraphMutation) -> SemioGraphSnapshot {
        let forward = operation.diff(base).diff().apply(base).expect("apply must succeed for a well-formed fixture");
        let backwards = operation.inverse(base);
        let mut restored = forward.clone();
        // 🔧️ Each inverse's diff must be computed against the CURRENT (`restored`) state, not the
        // stale pre-operation `base` — a whole-list-replace diff shape reconstructs the entire
        // collection from whatever base it is given, so diffing against the wrong base silently
        // discards the forward mutation's effect instead of undoing it (see `✳️text`'s own fix).
        for back in &backwards {
            restored = back.diff(&restored).diff().apply(&restored).expect("apply must succeed for a well-formed fixture");
        }
        assert_eq!(sorted_by_id(restored), sorted_by_id(base.clone()), "inverse must exactly restore the pre-operation fixture (order-insensitive over the id-keyed node/edge sets)");
        forward
    }

    #[semio_framework_async_macros::async_test]
    async fn create_delete_node_round_trips() {
        let base = fixture();
        let new_node = SemioGraphNode { id: GraphNodeId::new("n3"), kind: "extra".into(), label: "Extra".into(), position: SemioPoint2 { x: 5.0, y: 5.0 }, ports: vec![], properties: vec![] };

        let create = SemioGraphMutation::CreateNode(create_node::mutation::CreateNode {
            id: new_node.id.clone(),
            kind: new_node.kind.clone(),
            label: new_node.label.clone(),
            position: new_node.position.clone(),
            ports: new_node.ports.clone(),
            properties: new_node.properties.clone(),
        });
        let after_create = round_trip(&base, &create);
        assert_eq!(after_create.nodes.len(), base.nodes.len() + 1);
        assert_eq!(after_create.nodes.last().unwrap(), &new_node);

        let undo = create.inverse(&base);
        assert_eq!(undo, vec![SemioGraphMutation::DeleteNode(delete_node::mutation::DeleteNode { id: new_node.id.clone() })]);

        let delete = SemioGraphMutation::DeleteNode(delete_node::mutation::DeleteNode { id: GraphNodeId::new("n1") });
        let after_delete = round_trip(&base, &delete);
        assert_eq!(after_delete.nodes.len(), base.nodes.len() - 1);
        assert!(after_delete.edges.is_empty(), "delete-node must cascade-remove every severed edge");
    }

    #[semio_framework_async_macros::async_test]
    async fn delete_node_of_an_absent_id_has_an_empty_inverse() {
        let base = fixture();
        let delete = SemioGraphMutation::DeleteNode(delete_node::mutation::DeleteNode { id: GraphNodeId::new("absent") });
        assert!(delete.inverse(&base).is_empty(), "deleting an absent node has nothing to undo");
        assert_eq!(delete.diff(&base).diff().apply(&base).expect("apply must succeed for a well-formed fixture"), base, "an absent-id delete is a no-op");
    }

    #[semio_framework_async_macros::async_test]
    async fn delete_node_inverse_is_a_real_multi_mutation_cascade() {
        let base = fixture();
        let delete = SemioGraphMutation::DeleteNode(delete_node::mutation::DeleteNode { id: GraphNodeId::new("n1") });
        let undo = delete.inverse(&base);
        assert_eq!(undo.len(), 2, "inverse must restore the node AND every severed edge");
        assert_eq!(
            undo[0],
            SemioGraphMutation::CreateNode(create_node::mutation::CreateNode {
                id: GraphNodeId::new("n1"),
                kind: "source".into(),
                label: "Source".into(),
                position: SemioPoint2 { x: 0.0, y: 0.0 },
                ports: vec![SemioGraphPort { name: "out".into(), kind: SemioGraphPortKind::Out }],
                properties: vec![]
            })
        );
        assert_eq!(undo[1], SemioGraphMutation::CreateEdge(create_edge::mutation::CreateEdge { id: GraphEdgeId::new("e1"), source: GraphNodeId::new("n1"), target: GraphNodeId::new("n2"), kind: "flow".into(), label: "Main".into() }));
    }

    #[semio_framework_async_macros::async_test]
    async fn change_node_kind_and_label_and_move_node_round_trip() {
        let base = fixture();

        let change_kind = SemioGraphMutation::ChangeNodeKind(change_node_kind::mutation::ChangeNodeKind { id: GraphNodeId::new("n1"), new_kind: "relay".into() });
        let after = round_trip(&base, &change_kind);
        assert_eq!(after.nodes[0].kind, "relay");

        let change_label = SemioGraphMutation::ChangeNodeLabel(change_node_label::mutation::ChangeNodeLabel { id: GraphNodeId::new("n1"), new_label: "Renamed".into() });
        let after = round_trip(&base, &change_label);
        assert_eq!(after.nodes[0].label, "Renamed");

        let move_op = SemioGraphMutation::MoveNode(move_node::mutation::MoveNode { id: GraphNodeId::new("n1"), new_position: SemioPoint2 { x: 99.0, y: -1.0 } });
        let after = round_trip(&base, &move_op);
        assert_eq!(after.nodes[0].position, SemioPoint2 { x: 99.0, y: -1.0 });

        let missing = SemioGraphMutation::ChangeNodeKind(change_node_kind::mutation::ChangeNodeKind { id: GraphNodeId::new("absent"), new_kind: "x".into() });
        assert!(missing.inverse(&base).is_empty());
    }

    #[semio_framework_async_macros::async_test]
    async fn add_remove_node_port_round_trips() {
        let base = fixture();
        let port = SemioGraphPort { name: "extra".into(), kind: SemioGraphPortKind::InOut };

        let add = SemioGraphMutation::AddNodePort(add_node_port::mutation::AddNodePort { node_id: GraphNodeId::new("n2"), index: 0, port: port.clone() });
        let after_add = round_trip(&base, &add);
        assert_eq!(after_add.nodes[1].ports, vec![port.clone()]);

        let undo = add.inverse(&base);
        assert_eq!(undo, vec![SemioGraphMutation::RemoveNodePort(remove_node_port::mutation::RemoveNodePort { node_id: GraphNodeId::new("n2"), index: 0 })]);

        let remove = SemioGraphMutation::RemoveNodePort(remove_node_port::mutation::RemoveNodePort { node_id: GraphNodeId::new("n1"), index: 0 });
        let after_remove = round_trip(&base, &remove);
        assert!(after_remove.nodes[0].ports.is_empty());
    }

    #[semio_framework_async_macros::async_test]
    async fn add_remove_node_property_round_trips() {
        let base = fixture();
        let property = SemioValueEntry { key: "weight".into(), value: SemioValue::Int { lexeme: "7".into() } };

        let add = SemioGraphMutation::AddNodeProperty(add_node_property::mutation::AddNodeProperty { node_id: GraphNodeId::new("n1"), index: 0, property: property.clone() });
        let after_add = round_trip(&base, &add);
        assert_eq!(after_add.nodes[0].properties, vec![property.clone()]);

        let undo = add.inverse(&base);
        assert_eq!(undo, vec![SemioGraphMutation::RemoveNodeProperty(remove_node_property::mutation::RemoveNodeProperty { node_id: GraphNodeId::new("n1"), index: 0 })]);

        let remove = SemioGraphMutation::RemoveNodeProperty(remove_node_property::mutation::RemoveNodeProperty { node_id: GraphNodeId::new("absent"), index: 0 });
        assert!(remove.inverse(&base).is_empty());
        assert_eq!(remove.diff(&base).diff().apply(&base).expect("apply must succeed for a well-formed fixture"), base);
    }

    #[semio_framework_async_macros::async_test]
    async fn create_delete_edge_round_trips() {
        let base = fixture();
        let new_edge = SemioGraphEdge { id: GraphEdgeId::new("e2"), source: GraphNodeId::new("n2"), target: GraphNodeId::new("n1"), kind: "back".into(), label: "Return".into() };

        let create = SemioGraphMutation::CreateEdge(create_edge::mutation::CreateEdge { id: new_edge.id.clone(), source: new_edge.source.clone(), target: new_edge.target.clone(), kind: new_edge.kind.clone(), label: new_edge.label.clone() });
        let after_create = round_trip(&base, &create);
        assert_eq!(after_create.edges.last().unwrap(), &new_edge);

        let undo = create.inverse(&base);
        assert_eq!(undo, vec![SemioGraphMutation::DeleteEdge(delete_edge::mutation::DeleteEdge { id: new_edge.id.clone() })]);

        let delete = SemioGraphMutation::DeleteEdge(delete_edge::mutation::DeleteEdge { id: GraphEdgeId::new("e1") });
        let after_delete = round_trip(&base, &delete);
        assert!(after_delete.edges.is_empty());
        assert_eq!(after_delete.nodes.len(), base.nodes.len(), "delete-edge must not cascade into nodes");
    }

    #[semio_framework_async_macros::async_test]
    async fn semantic_kinds_cover_every_variant() {
        assert_eq!(SemioGraphMutation::kinds().len(), 11);
        let mutation = SemioGraphMutation::DeleteNode(delete_node::mutation::DeleteNode { id: GraphNodeId::new("n1") });
        assert_eq!(mutation.semantics().kind, "delete-node");
        assert_eq!(mutation.semantics().record, "DeletedNode");
        assert_eq!(mutation.target(), vec!["n1".to_string()]);
    }
}
//#endregion 🧪️Tests
